selector_to_html = {"a[href=\"#flaggems\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u57fa\u4e8e\u9884\u4f18\u5316\u5b9e\u73b0 FlagGems \u7684\u66f4\u597d\u6027\u80fd<a class=\"headerlink\" href=\"#flaggems\" title=\"Link to this heading\">#</a></h1><p>\u5c3d\u7ba1 <em>FlagGems</em> \u4e2d\u7684\u5185\u6838\u662f\u8bbe\u8ba1\u7528\u4e8e\u9ad8\u6027\u80fd\u4f7f\u7528\u573a\u666f\u7684\uff0c\u5728\u5b8c\u6574\u7684\u6a21\u578b\u90e8\u7f72\u73af\u5883\u4e2d\uff0c\n\u8981\u60f3\u5b9e\u73b0\u6700\u4f73\u7684\u7aef\u5230\u7aef\u6027\u80fd\uff0c\u4ecd\u7136\u9700\u8981\u7cbe\u5fc3\u5730\u96c6\u6210\u5e76\u4ed4\u7ec6\u8003\u67e5\u7cfb\u7edf\u7684\u8fd0\u884c\u65f6\u884c\u4e3a\u3002\n\u5c24\u5176\u662f\u8981\u6ce8\u610f\u4ee5\u4e0b\u4e24\u79cd\u5e38\u89c1\u7684\u6027\u80fd\u74f6\u9888\uff1a</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u9884\u4f18\u5316\u673a\u5236\u7684\u7528\u6cd5<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>\u5982\u679c\u5e0c\u671b\u8fdb\u4e00\u6b65\u4e86\u89e3\u7ec6\u8282\uff08\u4f8b\u5982\u5982\u4f55\u5b9a\u5236\u8c03\u4f18\u7f13\u5b58\u7684\u8def\u5f84\u548c\u914d\u7f6e\u7b49\uff09\uff0c\n\u53ef\u4ee5\u53c2\u9605\u6e90\u7801\u4ed3\u5e93\u4e2d\u7684 <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems/blob/v4.2.0/examples/pretune.py\"><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/pretune.py</span></code></a>\n\u6587\u4ef6\u3002</p>", "a[href=\"#libtuner\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><code class=\"docutils literal notranslate\"><span class=\"pre\">LibTuner</span></code> \u7684\u5de5\u4f5c\u539f\u7406<a class=\"headerlink\" href=\"#libtuner\" title=\"Link to this heading\">#</a></h3><p>\u5728\u5904\u7406\u65b0\u7684\u8f93\u5165\u5f62\u72b6\u65f6\uff0cTriton \u901a\u5e38\u4f1a\u5728\u524d\u51e0\u8f6e\u6267\u884c\u8fc7\u7a0b\u4e2d\u5f00\u5c55\u81ea\u52a8\u8c03\u4f18\u5de5\u4f5c\u3002\n\u8fd9\u4e9b\u8c03\u4f18\u52a8\u4f5c\u53ef\u80fd\u4f1a\u5bfc\u81f4\u7cfb\u7edf\u7684\u5ef6\u8fdf\u663e\u8457\u4e0a\u5347\uff0c\u5c24\u5176\u662f\u5728\u5bf9\u5ef6\u8fdf\u654f\u611f\u7684\u63a8\u7406\u7cfb\u7edf\u4e2d\u3002\n<code class=\"docutils literal notranslate\"><span class=\"pre\">LibTuner</span></code> \u89e3\u51b3\u8fd9\u4e00\u95ee\u9898\u7684\u65b9\u5f0f\u5982\u4e0b\uff1a</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9488\u5bf9\u63a8\u7406\u573a\u666f\u7684\u6a21\u578b\u5f62\u72b6\u9884\u4f18\u5316<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u6240\u63d0\u4f9b\u7684 <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems/blob/v4.2.0/src/flag_gems/utils/libentry.py#L206\"><code class=\"docutils literal notranslate\"><span class=\"pre\">LibTuner</span></code></a>\n\u7c7b\u53ef\u4ee5\u770b\u4f5c\u662f\u5bf9 Triton \u4e2d\u81ea\u52a8\u8c03\u4f18\u7cfb\u7edf\u7684\u4e00\u79cd\u8f7b\u91cf\u7ea7\u6539\u8fdb\u63aa\u65bd\u3002\n<code class=\"docutils literal notranslate\"><span class=\"pre\">LibTuner</span></code> \u5f15\u5165\u4e86\u4e00\u4e2a<strong>\u6301\u4e45\u7684\u3001\u6309\u8bbe\u5907\u7ec4\u7ec7\u7684\u8c03\u4f18\u7f13\u5b58</strong>\uff0c\n\u4e0e Triton \u7cfb\u7edf\u4e2d\u9ed8\u8ba4\u7684\u81ea\u52a8\u8c03\u4f18\u8fdb\u7a0b\u76f8\u6bd4\uff0c\u8fd9\u4e00\u7f13\u5b58\u6709\u52a9\u4e8e\u964d\u4f4e\u4e00\u4e9b\u8fd0\u884c\u65f6\u7684\u6027\u80fd\u5f00\u9500\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
